      FL_TRY(fl_cond(ctx, fl_t1981, &fl_t1985, error));
      fl_value fl_t1986 = fl_nothing();
      if (fl_t1985) {
        fl_value fl_t1987 = fl_nothing();
        FL_TRY(compiler_flang_citata_na_poverhnosti(ctx, golova, poverhnost, &fl_t1987, error));
        fl_t1986 = fl_t1987;
      } else {
        fl_t1986 = golova;
      }
      fl_value fl_t1988 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t1986, gotovo, &fl_t1988, error));
      const fl_value fl_t1989 = poverhnost;
      chasti = hvost;
      poverhnost = fl_t1989;
      citata = fl_t1979;
      gotovo = fl_t1988;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
