/* Тело «Беда спуска»; глубину считает обёртка ниже. */
static fl_status compiler_flang_beda_spuska_body(fl_ctx *ctx, fl_value vyzovy, fl_value mesto, fl_value parametr, fl_value skolko, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(vyzovy)) {
      *result = compiler_flang_text_375;
      return FL_OK;
    } else if (fl_chain_cons(vyzovy)) {
      const fl_value g = fl_chain_head(vyzovy); /* голова «г» */
      const fl_value h = fl_chain_tail(vyzovy); /* хвост «х» */
      fl_value fl_t32305 = fl_nothing();
      FL_TRY(compiler_flang_spusk_ne_strogiy(ctx, g, mesto, parametr, skolko, &fl_t32305, error));
      bool fl_t32306 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(fl_t32305, compiler_flang_text_375)), &fl_t32306, error));
      if (fl_t32306) {
        const fl_value fl_t32307 = mesto;
        const fl_value fl_t32308 = parametr;
        const fl_value fl_t32309 = skolko;
        vyzovy = h;
        mesto = fl_t32307;
        parametr = fl_t32308;
        skolko = fl_t32309;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Беда спуска", error));
        continue;
      } else {
        return compiler_flang_spusk_ne_strogiy(ctx, g, mesto, parametr, skolko, result, error);
      }
    } else {
      return fl_match_fail(ctx, vyzovy, error);
    }
  }
}

/*
 * Функция flang «Беда спуска».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param vyzovy — «вызовы»: список: «Значение»
 * @param mesto — «место»: число
 * @param parametr — «параметр»: строка
 * @param skolko — «сколько»: число
 * @return значение: строка
 */
fl_status compiler_flang_beda_spuska(fl_ctx *ctx, fl_value vyzovy, fl_value mesto, fl_value parametr, fl_value skolko, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Беда спуска", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = compiler_flang_beda_spuska_body(ctx, vyzovy, mesto, parametr, skolko, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

